select
a.union_id,
a.instance_id,
a.device_mete_id,
a.device_custom_id,
a.point_task_id,
a.if_robot,
a.if_video,
a.if_inferad,
a.if_artificial
from t_union_task_attr a
where 1 = 1
 and a.union_id = #{unionId, jdbcType=VARCHAR}
 and a.instance_id = #{instanceId, jdbcType=BIGINT}
 and a.device_mete_id = #{deviceMeteId, jdbcType=BIGINT}
 and a.device_custom_id = #{deviceCustomId, jdbcType=VARCHAR}
 and a.point_task_id = #{pointTaskId, jdbcType=BIGINT}
 and a.if_robot = #{ifRobot, jdbcType=INTEGER}
 and a.if_video = #{ifVideo, jdbcType=INTEGER}
 and a.if_inferad = #{ifInferad, jdbcType=INTEGER}
 and a.if_artificial = #{ifArtificial, jdbcType=INTEGER}

